            <el-table-column prop="tag" label="状态" min-width="100">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createtime" label="注册时间" min-width="180" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button
                  size="small"
                  :type="scope.row.tag === '已停用' ? 'success' : 'danger'"
                  @click="handleToggle(scope.row.nickname)"
                >
                  {{ scope.row.tag === '已停用' ? '启用' : '停用' }}
                </el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="member-manage__pagination-wrap">
        <div class="totalnum">
          <h3>会员统计</h3>
          <p>当前共 {{ tableData.length }} 位会员</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
